/// The existing OS current-executable acquisition route and its retained verified image.
///
/// No caller path or generic signed image can construct this type. This preserves
/// the existing current-path contract; it is not a new mapped-section kernel
/// identity proof. Update still binds the retained file to the located installation.
#[derive(Debug)]
pub struct VerifiedCurrentWindowsImage {
    verified: VerifiedWindowsImage,
    locator: PathBuf,
}
/// Failure phase of the single current-image acquisition route.
#[derive(Debug)]
pub enum WindowsCurrentImageError {
    /// Current path or image authentication failed under the existing image owner.
    Image(WindowsAuthenticodeError),
    /// Authentication succeeded, but the installed locator could not be resolved.
    Locator(std::io::Error),
}

impl VerifiedCurrentWindowsImage {
    /// Acquires the OS current executable, verifies through the single owner,
    /// then canonicalizes its locator while retaining the verified image.
    /// # Errors
    /// Refuses current-path, existing Authenticode or canonical locator failures.
    pub fn verify_current() -> Result<Self, WindowsCurrentImageError> {
        let executable = std::env::current_exe().map_err(|source| WindowsCurrentImageError::Image(windows_identity_error(
            format!("the current executable path is unavailable: {source}"),
            "Restore the signed package executable and relaunch it.",
        )))?;
        let verified = WindowsAuthenticodeImage::open(&executable)
            .and_then(WindowsAuthenticodeImage::verify)
            .map_err(WindowsCurrentImageError::Image)?;
        let locator = executable.canonicalize().map_err(WindowsCurrentImageError::Locator)?;
        Ok(Self { verified, locator })
    }
    /// The same image verified from the OS current-executable route.
    #[must_use]
    pub const fn image(&self) -> &VerifiedWindowsImage { &self.verified }
    /// Canonical locator only; the retained file supplies identity authority.
    #[must_use]
    pub fn locator(&self) -> &Path { &self.locator }
}

