/// Exact access requested for one retained destination object.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WindowsProfilePathAccess {
    /// Traverse this directory without recursive access.
    Traverse,
    /// Read and execute; recursive only for a directory.
    ReadExecute,
    /// Read/write/execute; recursive only for a directory.
    RolePrivate,
}

/// Native operation failure preserving its exact phase.
#[derive(Debug)]
pub struct WindowsGrantError { phase: &'static str, detail: String }
impl WindowsGrantError {
    fn error(phase: &'static str, detail: impl ToString) -> Self {
        Self { phase, detail: detail.to_string() }
    }
    fn status(phase: &'static str, status: u32) -> Self {
        Self::error(phase, format!("Win32 status {status}"))
    }
    /// Returns the phase and detail for the existing Runtime error registry.
    #[must_use]
    pub fn into_parts(self) -> (&'static str, String) { (self.phase, self.detail) }
}
impl std::fmt::Display for WindowsGrantError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.phase, self.detail)
    }
}
impl std::error::Error for WindowsGrantError {}

struct Allocation(*mut c_void);
impl Drop for Allocation {
    fn drop(&mut self) {
        if !self.0.is_null() {
            // SAFETY: one LocalAlloc-family allocation, freed exactly once.
            let _ = unsafe { LocalFree(self.0) };
        }
    }
}

/// Prepared merged ACL, still bound to the original retained object.
pub struct WindowsPreparedGrant<'registration> {
    _registration: &'registration WindowsProfileRegistration,
    authority:GrantWriteAuthority,
    original_aces: Vec<Vec<u8>>,
    destination: File,
    merged: Allocation,
    expected_aces: Vec<Vec<u8>>,
    package_sid: Vec<u8>,
    permissions: u32,
    inheritance: u32,
    prior_descriptor: String,
}

/// Observation of the exact object after its ACL write and readback.
#[derive(Debug)]
pub struct WindowsObservedGrant {
    destination: File,
    package_sid: Vec<u8>,
    permissions: u32,
    inheritance: u32,
    descriptor: String,
}
impl WindowsObservedGrant {
    /// Retains the exact kernel object identity, not a reopenable path claim.
    #[must_use]
    pub const fn destination(&self) -> &File { &self.destination }
    /// Copied bytes of the actual creating registration SID; never a raw pointer.
    #[must_use]
    pub fn package_sid(&self) -> &[u8] { &self.package_sid }
    /// Requested and read-back merged access mask.
    #[must_use]
    pub const fn permissions(&self) -> u32 { self.permissions }
    /// Requested and read-back inheritance bits.
    #[must_use]
    pub const fn inheritance(&self) -> u32 { self.inheritance }
    /// Full observed owner/DACL SDDL, point-in-time only.
    #[must_use]
    pub fn descriptor(&self) -> &str { &self.descriptor }
}

/// Failed publication retains the exact destination even if its ACL changed.
#[derive(Debug)]
pub struct WindowsGrantFailure { destination: File, error: WindowsGrantError }
impl WindowsGrantFailure {
    /// Returns custody and failure without retrying or undoing the write.
    #[must_use]
    pub fn into_parts(self) -> (File, WindowsGrantError) { (self.destination, self.error) }
}

impl WindowsProfileRegistration {
    /// Opens one path for the existing low-level grant API. No private-stage proof.
    /// # Errors
    /// Refuses NUL, reparse targets and native access/read/merge failures.
    pub fn prepare_path_grant(&self, path: &Path, access: WindowsProfilePathAccess)
        -> Result<WindowsPreparedGrant<'_>, WindowsGrantError>
    {
        use std::os::windows::ffi::OsStrExt as _;
        self.begin_legacy_grant().map_err(|detail|WindowsGrantError::error("generation grant authority",detail))?;
        if path.as_os_str().encode_wide().any(|unit| unit == 0) {
            return Err(WindowsGrantError::error("ACL path", "value contains NUL"));
        }
        let destination = OpenOptions::new()
            .access_mode(READ_CONTROL | WRITE_DAC | FILE_READ_ATTRIBUTES)
            .share_mode(FILE_SHARE_READ | FILE_SHARE_WRITE)
            .custom_flags(FILE_FLAG_BACKUP_SEMANTICS | FILE_FLAG_OPEN_REPARSE_POINT)
            .open(path).map_err(|e| WindowsGrantError::error("ACL object open", e))?;
        self.prepare_retained_grant(&destination, access)
    }

    /// Prepares a grant only through an already retained destination handle.
    /// # Errors
    /// Refuses deleted registrations, reparse objects and failed native queries.
    /// Installed source handles must not be supplied as grant destinations.
    pub fn prepare_retained_grant(&self, destination: &File, access: WindowsProfilePathAccess)
        -> Result<WindowsPreparedGrant<'_>, WindowsGrantError>
    {
        self.begin_legacy_grant().map_err(|detail|WindowsGrantError::error("generation grant authority",detail))?;
        self.prepare_retained_grant_inner(destination, access)
    }
    fn prepare_retained_grant_inner(&self, destination:&File, access:WindowsProfilePathAccess)
        -> Result<WindowsPreparedGrant<'_>,WindowsGrantError>
    {
        let destination = destination.try_clone()
            .map_err(|e| WindowsGrantError::error("ACL retained destination clone", e))?;
        let metadata = destination.metadata().map_err(|e| WindowsGrantError::error("ACL object metadata", e))?;
        if metadata.file_attributes() & FILE_ATTRIBUTE_REPARSE_POINT != 0 {
            return Err(WindowsGrantError::error("ACL object admission", "refuse a reparse-point grant target"));
        }
        let capabilities = self.capabilities().map_err(|e| WindowsGrantError::error("ACL profile", e))?;
        let sid = capabilities.as_native().AppContainerSid;
        // SAFETY: SID is the live valid allocation of this registration.
        let sid_length = usize::try_from(unsafe { GetLengthSid(sid) })
            .map_err(|e| WindowsGrantError::error("ACL package SID length", e))?;
        if !(8..=68).contains(&sid_length) {
            return Err(WindowsGrantError::error("ACL package SID", "invalid bounded native SID length"));
        }
        // SAFETY: validated length belongs to the retained native SID allocation.
        let package_sid = unsafe { std::slice::from_raw_parts(sid.cast::<u8>(), sid_length) }.to_vec();
        let prior_descriptor = descriptor(&destination)?;
        let (old_acl, old_descriptor) = read_acl(&destination)?;
        // SAFETY: old_descriptor retains the valid OS ACL allocation.
        let original_aces = unsafe { ace_bytes(old_acl) }?;
        let (permissions, inheritance) = access_parameters(metadata.is_dir(), access);
        let entry = EXPLICIT_ACCESS_W {
            grfAccessPermissions: permissions, grfAccessMode: SET_ACCESS, grfInheritance: inheritance,
            Trustee: TRUSTEE_W { pMultipleTrustee: std::ptr::null_mut(), MultipleTrusteeOperation: NO_MULTIPLE_TRUSTEE,
                TrusteeForm: TRUSTEE_IS_SID, TrusteeType: TRUSTEE_IS_USER, ptstrName: sid.cast() },
        };
        let mut merged = std::ptr::null_mut();
        // SAFETY: the original ACL allocation and registration SID remain live.
        let status = unsafe { SetEntriesInAclW(1, &raw const entry, old_acl, &raw mut merged) };
        if status != ERROR_SUCCESS { return Err(WindowsGrantError::status("filesystem DACL merge", status)); }
        let merged = Allocation(merged.cast());
        // SAFETY: SetEntriesInAclW returned this valid allocated ACL.
        let expected_aces = unsafe { ace_bytes(merged.0.cast()) }?;
        drop(old_descriptor);
        Ok(WindowsPreparedGrant { _registration: self, authority:GrantWriteAuthority::Legacy, original_aces, destination, merged, expected_aces, package_sid, permissions, inheritance, prior_descriptor })
    }
}

impl WindowsPreparedGrant<'_> {
    /// Preserves the old low-level result while using the single observed writer.
    /// # Errors
    /// Any write/readback refusal fails; ACL effects may already have occurred.
    pub fn publish(self) -> Result<(), WindowsGrantError> {
        self.publish_observed().map(|_| ()).map_err(|failure| failure.into_parts().1)
    }
    /// Publishes and observes through the same retained object, retaining it on failure.
    /// # Errors
    /// Refuses failed writes, descriptor queries or a changed merged ACL/control prefix.
    pub fn publish_observed(self) -> Result<WindowsObservedGrant, WindowsGrantFailure> {
        let result = self.write_and_read();
        match result {
            Ok(descriptor) => Ok(WindowsObservedGrant { destination: self.destination, package_sid: self.package_sid,
                permissions: self.permissions, inheritance: self.inheritance, descriptor }),
            Err(error) => Err(WindowsGrantFailure { destination: self.destination, error }),
        }
    }
    fn write_and_read(&self) -> Result<String, WindowsGrantError> {
        // A legacy preparation made before reservation must not publish after
        // a strict claim took ownership of the same profile.
        if !grant_write_allowed(self.authority,self._registration.generation_claimed()) {
            return Err(WindowsGrantError::error("generation grant authority","prepared grant no longer owns mutation authority"));
        }
        // Reject known stale preparation before mutation. This is not an atomic
        // compare-and-swap; the stage owner must exclude concurrent ACL writers.
        let (current, _current_allocation) = read_acl(&self.destination)?;
        // SAFETY: _current_allocation retains the returned native ACL.
        if unsafe { ace_bytes(current) }? != self.original_aces
            || descriptor(&self.destination)? != self.prior_descriptor
        {
            return Err(WindowsGrantError::error("filesystem DACL stale preparation", "destination descriptor changed before publication"));
        }
        // SAFETY: retained WRITE_DAC handle and merged native ACL remain live.
        let status = unsafe { SetSecurityInfo(self.destination.as_raw_handle().cast(), SE_FILE_OBJECT,
            DACL_SECURITY_INFORMATION, std::ptr::null_mut(), std::ptr::null_mut(), self.merged.0.cast(), std::ptr::null()) };
        if status != ERROR_SUCCESS { return Err(WindowsGrantError::status("filesystem DACL write", status)); }
        let (actual, _allocation) = read_acl(&self.destination)?;
        // SAFETY: read_acl returned a live native ACL owned by _allocation.
        let actual_aces = unsafe { ace_bytes(actual) }?;
        if actual_aces != self.expected_aces {
            return Err(WindowsGrantError::error("filesystem DACL readback", "actual ACE sequence differs from merged grant"));
        }
        validate_package_grant(&self.original_aces, &actual_aces, &self.package_sid,
            self.permissions, self.inheritance)?;
        let actual = descriptor(&self.destination)?;
        if actual.split('(').next() != self.prior_descriptor.split('(').next() {
            return Err(WindowsGrantError::error("filesystem DACL readback", "owner or DACL control prefix changed"));
        }
        Ok(actual)
    }
}

fn descriptor(file: &File) -> Result<String, WindowsGrantError> {
    use windows_permissions::constants::{SeObjectType, SecurityInformation};
    let value = windows_permissions::wrappers::GetSecurityInfo(file, SeObjectType::SE_FILE_OBJECT,
        SecurityInformation::Owner | SecurityInformation::Dacl)
        .map_err(|e| WindowsGrantError::error("filesystem descriptor read", e))?;
    value.as_sddl().map(|s| s.to_string_lossy().into_owned())
        .map_err(|e| WindowsGrantError::error("filesystem descriptor serialization", e))
}
fn read_acl(file: &File) -> Result<(*mut ACL, Allocation), WindowsGrantError> {
    let mut acl = std::ptr::null_mut(); let mut descriptor = std::ptr::null_mut();
    // SAFETY: live READ_CONTROL file and writable native output slots.
    let status = unsafe { GetSecurityInfo(file.as_raw_handle().cast(), SE_FILE_OBJECT, DACL_SECURITY_INFORMATION,
        std::ptr::null_mut(), std::ptr::null_mut(), &raw mut acl, std::ptr::null_mut(), &raw mut descriptor) };
    if status != ERROR_SUCCESS { return Err(WindowsGrantError::status("filesystem DACL read", status)); }
    Ok((acl, Allocation(descriptor)))
}

// Callers must retain a valid OS-allocated ACL throughout this bounded copy.
unsafe fn ace_bytes(acl: *const ACL) -> Result<Vec<Vec<u8>>, WindowsGrantError> {
    if acl.is_null() { return Err(WindowsGrantError::error("filesystem ACL snapshot", "null DACL refused")); }
    // SAFETY: caller guarantees a valid native ACL allocation.
    let header = unsafe { &*acl };
    let start = acl as usize;
    let end = start.checked_add(usize::from(header.AclSize)).ok_or_else(|| WindowsGrantError::error("filesystem ACL snapshot", "extent overflow"))?;
    let header_end = start.checked_add(std::mem::size_of::<ACL>()).ok_or_else(|| WindowsGrantError::error("filesystem ACL snapshot", "header overflow"))?;
    if header_end > end || usize::from(header.AceCount) > (end - header_end) / std::mem::size_of::<ACE_HEADER>() {
        return Err(WindowsGrantError::error("filesystem ACL snapshot", "invalid bounded ACL count"));
    }
    let mut result = Vec::with_capacity(usize::from(header.AceCount));
    for index in 0..u32::from(header.AceCount) {
        let mut ace = std::ptr::null_mut();
        // SAFETY: native API validates the index against the valid ACL.
        if unsafe { GetAce(acl, index, &raw mut ace) } == 0 {
            return Err(WindowsGrantError::error("filesystem ACL snapshot", std::io::Error::last_os_error()));
        }
        let at = ace as usize;
        if at < header_end || at.checked_add(std::mem::size_of::<ACE_HEADER>()).is_none_or(|limit| limit > end) {
            return Err(WindowsGrantError::error("filesystem ACL snapshot", "ACE header outside ACL"));
        }
        // SAFETY: header extent checked above and pointer is returned by GetAce.
        let size = usize::from(unsafe { (*ace.cast::<ACE_HEADER>()).AceSize });
        if size < std::mem::size_of::<ACE_HEADER>() || at.checked_add(size).is_none_or(|limit| limit > end) {
            return Err(WindowsGrantError::error("filesystem ACL snapshot", "ACE extent outside ACL"));
        }
        // SAFETY: entire ACE extent lies in the retained native ACL allocation.
        result.push(unsafe { std::slice::from_raw_parts(ace.cast::<u8>(), size) }.to_vec());
    }
    Ok(result)
}

impl std::fmt::Debug for WindowsPreparedGrant<'_> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("WindowsPreparedGrant").field("destination", &self.destination)
            .field("permissions", &self.permissions).field("inheritance", &self.inheritance).finish_non_exhaustive()
    }
}

// Interpret only the SDK's ordinary ACCESS_ALLOWED_ACE layout in owned bytes.
// The SID is compared opaquely with the exact native registration copy; no SID
// fields, object/conditional ACE payloads or general ACL grammar are parsed.
fn package_allow(ace: &[u8], sid: &[u8]) -> bool {
    let offset = std::mem::offset_of!(ACCESS_ALLOWED_ACE, SidStart);
    ace.first().copied().map(u32::from) == Some(ACCESS_ALLOWED_ACE_TYPE)
        && ace.get(offset..) == Some(sid)
}

fn validate_package_grant(
    before: &[Vec<u8>], after: &[Vec<u8>], sid: &[u8], mask: u32, flags: u32,
) -> Result<(), WindowsGrantError> {
    let mut package = after.iter().filter(|ace| package_allow(ace, sid));
    let ace = package.next().ok_or_else(|| WindowsGrantError::error("filesystem package grant readback", "actual package allow ACE missing"))?;
    let mask_offset = std::mem::offset_of!(ACCESS_ALLOWED_ACE, Mask);
    if package.next().is_some()
        || ace.get(std::mem::offset_of!(ACE_HEADER, AceFlags)).copied().map(u32::from) != Some(flags)
        || ace.get(mask_offset..mask_offset + 4) != Some(mask.to_le_bytes().as_slice())
    {
        return Err(WindowsGrantError::error("filesystem package grant readback", "actual package mask, inheritance or cardinality differs"));
    }
    let old_other = before.iter().filter(|ace| !package_allow(ace, sid));
    let new_other = after.iter().filter(|ace| !package_allow(ace, sid));
    if !old_other.eq(new_other) {
        return Err(WindowsGrantError::error("filesystem package grant readback", "unrelated ACE bytes or order changed"));
    }
    Ok(())
}

fn access_parameters(directory: bool, access: WindowsProfilePathAccess) -> (u32, u32) {
    let permissions = match access {
        WindowsProfilePathAccess::Traverse => FILE_TRAVERSE,
        WindowsProfilePathAccess::ReadExecute => FILE_GENERIC_READ | FILE_GENERIC_EXECUTE,
        WindowsProfilePathAccess::RolePrivate => FILE_GENERIC_READ | FILE_GENERIC_WRITE | FILE_GENERIC_EXECUTE,
    };
    let inheritance = if directory && access != WindowsProfilePathAccess::Traverse {
        SUB_CONTAINERS_AND_OBJECTS_INHERIT
    } else { 0 };
    (permissions, inheritance)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn exact_access_masks_and_inheritance_are_preserved() {
        for directory in [false, true] {
            assert_eq!(access_parameters(directory, WindowsProfilePathAccess::Traverse), (0x20, 0));
            let inheritance = if directory { 3 } else { 0 };
            assert_eq!(access_parameters(directory, WindowsProfilePathAccess::ReadExecute), (0x12_00a9, inheritance));
            assert_eq!(access_parameters(directory, WindowsProfilePathAccess::RolePrivate), (0x12_01bf, inheritance));
        }
    }
    fn fixture_ace(sid: &[u8], mask: u32, flags: u8) -> Vec<u8> {
        let sid_offset = std::mem::offset_of!(ACCESS_ALLOWED_ACE, SidStart);
        let mut ace = vec![0; sid_offset + sid.len()];
        ace[0] = u8::try_from(ACCESS_ALLOWED_ACE_TYPE).expect("SDK allow ACE type fits byte");
        ace[std::mem::offset_of!(ACE_HEADER, AceFlags)] = flags;
        let size = u16::try_from(ace.len()).unwrap().to_le_bytes();
        let size_offset = std::mem::offset_of!(ACE_HEADER, AceSize);
        ace[size_offset..size_offset + 2].copy_from_slice(&size);
        let mask_offset = std::mem::offset_of!(ACCESS_ALLOWED_ACE, Mask);
        ace[mask_offset..mask_offset + 4].copy_from_slice(&mask.to_le_bytes());
        ace[sid_offset..].copy_from_slice(sid);
        ace
    }

    #[test]
    fn observed_package_fields_are_checked_independently_of_merged_bytes() {
        // Owned-byte validator fixtures only, not native SID/ACL evidence.
        let sid = [1, 2, 3, 4];
        let other = fixture_ace(&[9, 8, 7, 6], 0x1234, 0);
        let before = vec![other.clone()];
        let correct = fixture_ace(&sid, 0x12_00a9, 3);
        assert!(validate_package_grant(&before, &[other.clone(), correct.clone()], &sid, 0x12_00a9, 3).is_ok());
        for bad in [fixture_ace(&[0, 0, 0, 0], 0x12_00a9, 3),
            fixture_ace(&sid, 0x12_01bf, 3), fixture_ace(&sid, 0x12_00a9, 0)] {
            assert!(validate_package_grant(&before, &[other.clone(), bad], &sid, 0x12_00a9, 3).is_err());
        }
        assert!(validate_package_grant(&before, &before, &sid, 0x12_00a9, 3).is_err());
        assert!(validate_package_grant(&before, &[other, correct.clone(), correct], &sid, 0x12_00a9, 3).is_err());
    }

    #[test]
    fn unrelated_ace_payloads_must_be_preserved_byte_for_byte() {
        let sid = [1, 2, 3, 4];
        // Opaque nonordinary ACE payload: no semantic normalization may erase it.
        let unrelated = vec![42, 0, 7, 0, 9, 8, 7];
        let before = vec![unrelated.clone()];
        let correct = fixture_ace(&sid, 0x12_00a9, 0);
        assert!(validate_package_grant(&before, &[unrelated.clone(), correct.clone()], &sid, 0x12_00a9, 0).is_ok());
        assert!(validate_package_grant(&before, &[correct.clone()], &sid, 0x12_00a9, 0).is_err());
        let mut changed = unrelated; changed[6] ^= 1;
        assert!(validate_package_grant(&before, &[changed, correct], &sid, 0x12_00a9, 0).is_err());
    }

}

/// Identity of one retained file object in the FileIdInfo domain.
/// This is the volume serial and all 128 file-ID bits, never cap-std's 64-bit inode.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct WindowsGrantedObjectIdentity {
    volume: u64,
    file: [u8; 16],
}
impl WindowsGrantedObjectIdentity {
    /// Exact queried volume serial.
    #[must_use]
    pub const fn volume(&self) -> u64 { self.volume }
    /// Exact queried 128-bit file identity.
    #[must_use]
    pub const fn file(&self) -> &[u8; 16] { &self.file }
}

/// Opaque grant readback after this operation's writable handles have closed.
/// The retained handle has only READ_CONTROL and FILE_READ_ATTRIBUTES. This is
/// point-in-time custody, not global closure, namespace sealing or a role permit.
#[derive(Debug)]
pub struct WindowsClosedGrantReceipt {
    registration: std::rc::Rc<WindowsProfileRegistration>,
    destination: File,
    identity: WindowsGrantedObjectIdentity,
    snapshot: ClosedGrantSnapshot,
}
#[derive(Debug)]
struct ClosedGrantSnapshot {
    package_sid: Vec<u8>, permissions: u32, inheritance: u32, descriptor: String,
}
impl WindowsClosedGrantReceipt {
    /// Same supervisor-local registration retained by the sole grant writer.
    #[must_use]
    pub fn registration(&self) -> &std::rc::Rc<WindowsProfileRegistration> { &self.registration }
    /// Read-control/metadata-only handle; cloning cannot restore WRITE_DAC.
    #[must_use]
    pub const fn destination(&self) -> &File { &self.destination }
    /// Exact object identity re-read through the reduced handle after writer closure.
    #[must_use]
    pub const fn object_identity(&self) -> WindowsGrantedObjectIdentity { self.identity }
    /// Package SID observed by the existing writer.
    #[must_use]
    pub fn package_sid(&self) -> &[u8] { &self.snapshot.package_sid }
    /// Existing writer's independently checked permission mask.
    #[must_use]
    pub const fn permissions(&self) -> u32 { self.snapshot.permissions }
    /// Existing writer's independently checked inheritance flags.
    #[must_use]
    pub const fn inheritance(&self) -> u32 { self.snapshot.inheritance }
    /// Owner/DACL snapshot rechecked after closing this operation's writable handles.
    #[must_use]
    pub fn descriptor(&self) -> &str { &self.snapshot.descriptor }
    /// Requires a separate retained stage pin to name this same volume/128-bit object.
    /// # Errors
    /// Refuses a different object or unsupported identity query; never coerces 64-bit IDs.
    pub fn require_same_object(&self,other:&File) -> Result<(),WindowsGrantError> {
        if query_granted_object(other)?!=self.identity {
            return Err(WindowsGrantError::error("grant stage identity","retained stage pin differs"));
        }
        self.revalidate()
    }
    /// Rechecks the same retained object and descriptor, without a path reopen.
    /// # Errors
    /// Refuses object-identity or descriptor drift and native query failures.
    pub fn revalidate(&self) -> Result<(), WindowsGrantError> {
        require_closed_observation(self.identity, &self.snapshot.descriptor, &self.destination)
    }
}

#[derive(Debug)]
struct GrantClosureCustody {
    registration: std::rc::Rc<WindowsProfileRegistration>,
    // Exactly one writable owner remains here on preparation/publication failure.
    destination: Option<File>,
    observation: Option<WindowsObservedGrant>,
    reduced: Option<File>,
    identity: Option<WindowsGrantedObjectIdentity>,
    snapshot: Option<ClosedGrantSnapshot>,
}
/// Failure retains registration, original/observed object, any reduced handle and
/// completed observations. It provides no retry transition or cleanup assertion.
#[derive(Debug)]
pub struct WindowsGrantReceiptFailure { custody: GrantClosureCustody, error: WindowsGrantError }
impl WindowsGrantReceiptFailure {
    /// Exact failed phase; custody stays in this value.
    #[must_use]
    pub const fn error(&self) -> &WindowsGrantError { &self.error }
    /// Retained creating registration, including after post-close readback failure.
    #[must_use]
    pub fn registration(&self) -> &std::rc::Rc<WindowsProfileRegistration> { &self.custody.registration }
    /// Whether this operation has a reduced handle retained for reconciliation.
    #[must_use]
    pub fn reduced_destination(&self) -> Option<&File> { self.custody.reduced.as_ref() }
}

impl WindowsProfileRegistration {
    /// Publishes through the sole retained ACL writer and closes this operation's
    /// writable helper handles before minting an opaque read-control receipt.
    /// The caller transfers its helper File, rather than retaining another clone.
    /// Other stage/host handles are not claimed closed by this operation.
    /// # Errors
    /// Refuses failed preparation/publication, handle reduction, identity or ACL
    /// readback. Every failure retains all acquired custody; never automatically retry.
    pub fn publish_owned_retained_grant(
        registration: std::rc::Rc<Self>, destination: File, access: WindowsProfilePathAccess,
    ) -> Result<WindowsClosedGrantReceipt, WindowsGrantReceiptFailure> {
        Self::publish_owned_retained_grant_inner(registration,destination,access,None)
    }
    #[cfg(feature = "qualification-catalog")]
    pub(crate) fn publish_generation_retained_grant(
        claim:&crate::WindowsGenerationGrantClaim, destination:File, access:WindowsProfilePathAccess,
    ) -> Result<WindowsClosedGrantReceipt,WindowsGrantReceiptFailure> {
        let registration=std::rc::Rc::clone(claim.registration());
        Self::publish_owned_retained_grant_inner(registration,destination,access,Some(claim.registration().as_ref()))
    }
    fn publish_owned_retained_grant_inner(
        registration:std::rc::Rc<Self>, destination:File, access:WindowsProfilePathAccess,
        claim_registration:Option<&Self>,
    ) -> Result<WindowsClosedGrantReceipt,WindowsGrantReceiptFailure> {
        let mut custody=GrantClosureCustody { registration,destination:Some(destination),
            observation:None,reduced:None,identity:None,snapshot:None };
        // Preparation borrows only registration; its own destination duplicate is
        // independent of the incoming handle. The owned Rc outlives the writer.
        let creating_registration=std::rc::Rc::clone(&custody.registration);
        let preparation=match claim_registration {
            Some(claim) if std::ptr::eq(claim, creating_registration.as_ref()) && claim.generation_claimed() =>
                creating_registration.prepare_retained_grant_inner(custody.destination.as_ref().expect("new custody destination"),access)
                    .map(|mut prepared| { prepared.authority=GrantWriteAuthority::GenerationClaim;prepared }),
            Some(_)=>Err(WindowsGrantError::error("generation grant authority","claim differs from registration")),
            None=>creating_registration.prepare_retained_grant(custody.destination.as_ref().expect("new custody destination"),access),
        };
        let prepared=match preparation {
            Ok(value)=>value,
            Err(error)=>return Err(WindowsGrantReceiptFailure { custody,error }),
        };
        drop(custody.destination.take());
        match prepared.publish_observed() {
            Ok(value)=>custody.observation=Some(value),
            Err(failure)=>{
                let (destination,error)=failure.into_parts();
                custody.destination=Some(destination);
                return Err(WindowsGrantReceiptFailure { custody,error });
            }
        }
        let observed=custody.observation.as_ref().expect("published observation");
        match query_granted_object(&observed.destination) {
            Ok(identity)=>custody.identity=Some(identity),
            Err(error)=>return Err(WindowsGrantReceiptFailure { custody,error }),
        }
        match duplicate_read_control(&observed.destination) {
            Ok(reduced)=>custody.reduced=Some(reduced),
            Err(error)=>return Err(WindowsGrantReceiptFailure { custody,error }),
        }
        let WindowsObservedGrant { destination,package_sid,permissions,inheritance,descriptor }=
            custody.observation.take().expect("published observation retained");
        custody.snapshot=Some(ClosedGrantSnapshot { package_sid,permissions,inheritance,descriptor });
        drop(destination);
        // This operation now retains no WRITE_DAC handle. The actual reduced
        // object's identity and owner/DACL are read again after that close.
        let identity=custody.identity.expect("queried object identity");
        let snapshot=custody.snapshot.as_ref().expect("retained grant snapshot");
        let reduced=custody.reduced.as_ref().expect("retained reduced handle");
        if let Err(error)=require_closed_observation(identity,&snapshot.descriptor,reduced) {
            return Err(WindowsGrantReceiptFailure { custody,error });
        }
        Ok(WindowsClosedGrantReceipt { registration:custody.registration,
            destination:custody.reduced.expect("validated reduced handle"),identity,
            snapshot:custody.snapshot.expect("validated snapshot") })
    }
}

fn duplicate_read_control(source:&File) -> Result<File,WindowsGrantError> {
    use std::os::windows::io::FromRawHandle as _;
    use windows_sys::Win32::Foundation::DuplicateHandle;
    use windows_sys::Win32::System::Threading::GetCurrentProcess;
    let mut raw=std::ptr::null_mut();
    // SAFETY: live File source, current-process pseudo handles, writable output;
    // options0 means explicit desired access (never SAME_ACCESS/CLOSE_SOURCE),
    // false inherit. The unique success handle is immediately owned by File.
    let success=unsafe { DuplicateHandle(GetCurrentProcess(),source.as_raw_handle().cast(),
        GetCurrentProcess(),&raw mut raw,READ_CONTROL|FILE_READ_ATTRIBUTES,0,0) };
    if success==0 { return Err(WindowsGrantError::error("grant handle reduction",std::io::Error::last_os_error())); }
    if raw.is_null() { return Err(WindowsGrantError::error("grant handle reduction","success returned null handle")); }
    // SAFETY: successful DuplicateHandle returned this one owned, non-null handle.
    Ok(unsafe { File::from_raw_handle(raw.cast()) })
}
fn query_granted_object(file:&File) -> Result<WindowsGrantedObjectIdentity,WindowsGrantError> {
    use windows_sys::Win32::Storage::FileSystem::{FILE_ID_INFO,FILE_ID_128,FileIdInfo,GetFileInformationByHandleEx};
    let mut info=FILE_ID_INFO { VolumeSerialNumber:0,FileId:FILE_ID_128 { Identifier:[0;16] } };
    let size=u32::try_from(std::mem::size_of::<FILE_ID_INFO>()).map_err(|e|WindowsGrantError::error("grant object identity",e))?;
    // SAFETY: live retained file and correctly sized initialized FILE_ID_INFO
    // output. FileIdInfo writes only this object; no path or caller ID is used.
    if unsafe { GetFileInformationByHandleEx(file.as_raw_handle().cast(),FileIdInfo,
        (&raw mut info).cast(),size) }==0 {
        return Err(WindowsGrantError::error("grant object identity",std::io::Error::last_os_error()));
    }
    Ok(WindowsGrantedObjectIdentity { volume:info.VolumeSerialNumber,file:info.FileId.Identifier })
}
fn require_closed_observation(expected:WindowsGrantedObjectIdentity,expected_descriptor:&str,file:&File) -> Result<(),WindowsGrantError> {
    if query_granted_object(file)?!=expected {
        return Err(WindowsGrantError::error("grant post-close identity","retained object differs"));
    }
    if descriptor(file)?!=expected_descriptor {
        return Err(WindowsGrantError::error("grant post-close descriptor","owner/DACL changed after writer closure"));
    }
    Ok(())
}

