            destination,WindowsProfilePathAccess::ReadExecute).expect_err("READ_CONTROL missing at prepare");
        assert!(std::rc::Rc::ptr_eq(&registration,failure.registration()));
        assert_eq!(std::rc::Rc::strong_count(&registration),2);
