        assert!(failure.custody.observation.is_none());assert!(failure.reduced_destination().is_none());
        drop(failure);
        let mut registration=std::rc::Rc::try_unwrap(registration).expect("sole registration after failure retirement");
        registration.delete_checked().expect("exact checked profile cleanup");drop(registration);
        std::fs::remove_file(path).unwrap();std::fs::remove_dir(root).unwrap();
    }
