//! Owning registration input for Windows generation preparation.
//!
//! This owner records actual profile creation, not Strict admission, ACL
//! application, kernel token properties, inherited authority or catalog trust.

// Proposed exact owner relocation; repository allowance review is required
// before adoption. Only registration create/delete and owned SID release use FFI.
#![allow(unsafe_code)]
#![deny(unsafe_op_in_unsafe_fn)]

use std::ffi::OsStr;
use std::marker::PhantomData;
use std::os::windows::ffi::OsStrExt as _;
use windows_sys::Win32::Security::Isolation::{CreateAppContainerProfile, DeleteAppContainerProfile};
use windows_sys::Win32::Security::{FreeSid, PSID, SECURITY_CAPABILITIES};

/// Failure from the single owning profile registration implementation.
#[derive(Debug)]
pub struct WindowsProfileRegistrationError {
    phase: &'static str,
    detail: String,
}

impl WindowsProfileRegistrationError {
    fn contract(phase: &'static str, detail: impl Into<String>) -> Self {
        Self { phase, detail: detail.into() }
    }

    fn status(phase: &'static str, status: i32) -> Self {
        Self::contract(phase, format!("HRESULT/NT status 0x{:08x}", status.cast_unsigned()))
    }

    /// Preserves the native operation and detail for the caller's error registry.
    #[must_use]
    pub fn into_parts(self) -> (&'static str, String) {
        (self.phase, self.detail)
    }
}

impl std::fmt::Display for WindowsProfileRegistrationError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.phase, self.detail)
    }
}

impl std::error::Error for WindowsProfileRegistrationError {}

/// One newly created registration and its exact native SID allocation.
///
/// Creation refuses an existing name. No `Send`/`Sync` assertion is supplied;
/// this owner stays with its generation. Drop is best-effort only: ordered
/// retirement must call checked deletion before claiming cleanup completed.
#[derive(Debug)]
pub struct WindowsProfileRegistration {
    name: Vec<u16>,
    sid: PSID,
    deleted: bool,
    grant_state:std::cell::Cell<RegistrationGrantState>,
}

impl WindowsProfileRegistration {
    /// Creates exactly one new profile with zero capabilities.
    ///
    /// # Errors
    /// Refuses an embedded NUL, an existing name, native failure, or a success
    /// response without a SID. No existing profile is opened or adopted.
    pub fn create(name: &OsStr) -> Result<Self, WindowsProfileRegistrationError> {
        let mut name: Vec<u16> = name.encode_wide().collect();
        if name.contains(&0) {
            return Err(WindowsProfileRegistrationError::contract(
                "AppContainer profile name", "value contains NUL",
            ));
        }
        name.push(0);
        let mut sid = std::ptr::null_mut();
        // SAFETY: all names are live NUL-terminated UTF-16; capability count
        // and pointer are empty; sid is a writable output slot.
        let status = unsafe {
            CreateAppContainerProfile(name.as_ptr(), name.as_ptr(), name.as_ptr(),
                std::ptr::null(), 0, &raw mut sid)
        };
        if status < 0 {
            return Err(WindowsProfileRegistrationError::status("CreateAppContainerProfile", status));
        }
        if sid.is_null() {
            // SAFETY: successful creation identified this exact name, but gave
            // no usable SID owner. Remove only that newly created registration.
            let cleanup = unsafe { DeleteAppContainerProfile(name.as_ptr()) };
            return Err(WindowsProfileRegistrationError::contract(
                "CreateAppContainerProfile",
                format!("success returned a null package SID; exact name UTF-16 {name:?}; cleanup status 0x{:08x}", cleanup.cast_unsigned()),
            ));
        }
        Ok(Self { name, sid, deleted: false, grant_state:std::cell::Cell::new(RegistrationGrantState::Fresh) })
    }

    /// Borrows the exact registered SID as a zero-capability native descriptor.
    ///
    /// This is requested creation input, not an observation of a child token.
    ///
    /// # Errors
    /// Refuses use after this owner has explicitly deleted its registration.
    pub fn capabilities(&self) -> Result<WindowsProfileCapabilities<'_>, WindowsProfileRegistrationError> {
        if self.deleted {
            return Err(WindowsProfileRegistrationError::contract(
                "AppContainer profile capabilities", "registration already deleted",
            ));
        }
        Ok(WindowsProfileCapabilities {
            native: SECURITY_CAPABILITIES {
                AppContainerSid: self.sid,
                Capabilities: std::ptr::null_mut(),
                CapabilityCount: 0,
                Reserved: 0,
            },
            registration: PhantomData,
        })
    }

    /// Deletes only this owner's exact registration and disables Drop deletion.
    ///
    /// # Errors
    /// Fails on a repeated explicit deletion or a non-success native result.
    /// Failure preserves the owner for explicit quarantine/recovery; deleting a
    /// registration is never proof that any process has retired.
    pub fn delete_checked(&mut self) -> Result<(), WindowsProfileRegistrationError> {
        if self.deleted {
            return Err(WindowsProfileRegistrationError::contract(
                "DeleteAppContainerProfile", "registration already deleted",
            ));
        }
        // SAFETY: this owner's exact name remains live and NUL terminated.
        let status = unsafe { DeleteAppContainerProfile(self.name.as_ptr()) };
        if status != 0 {
            return Err(WindowsProfileRegistrationError::status("DeleteAppContainerProfile", status));
        }
        self.deleted = true;
        Ok(())
    }
}

impl Drop for WindowsProfileRegistration {
    fn drop(&mut self) {
        if !self.deleted {
            // SAFETY: only the registration created by this owner is selected.
            let _ = unsafe { DeleteAppContainerProfile(self.name.as_ptr()) };
        }
        // SAFETY: this is the one non-null SID allocation returned by creation.
        let _ = unsafe { FreeSid(self.sid) };
    }
}

/// Lifetime-bound native input; backing SID ownership remains in registration.
///
/// Keep this value at a stable address after registering its descriptor with a
/// process attribute list. A caller must not treat its raw SID as independently
/// owned or keep using it after this registration owner is released.
pub struct WindowsProfileCapabilities<'registration> {
    native: SECURITY_CAPABILITIES,
    registration: PhantomData<&'registration WindowsProfileRegistration>,
}

impl WindowsProfileCapabilities<'_> {
    /// Borrows the native descriptor for synchronous attribute preparation.
    #[must_use]
    pub const fn as_native(&self) -> &SECURITY_CAPABILITIES {
        &self.native
    }
}

impl std::fmt::Debug for WindowsProfileCapabilities<'_> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("WindowsProfileCapabilities")
            .field("capability_count", &self.native.CapabilityCount)
            .finish_non_exhaustive()
    }
}

