#[cfg(feature = "qualification-catalog")]
mod generation;
#[cfg(feature = "qualification-catalog")]
pub use generation::{WindowsGenerationGrantClaim, WindowsGenerationResourceRole,
    WindowsGenerationClaimFailure, WindowsGenerationGrantedMember, WindowsPreparedGenerationResources,
    WindowsGenerationResourceDigest, WindowsGenerationPreparationFailure};
impl WindowsProfileRegistration {
    pub(crate) fn generation_claimed(&self) -> bool { self.grant_state.get()==RegistrationGrantState::GenerationReserved }
    pub(crate) fn begin_legacy_grant(&self)->Result<(),&'static str> { begin_legacy_grant_state(&self.grant_state) }
}

#[derive(Debug,Clone,Copy,PartialEq,Eq)]
enum RegistrationGrantState { Fresh, LegacyGrantAttempted, GenerationReserved }
fn begin_legacy_grant_state(state:&std::cell::Cell<RegistrationGrantState>)->Result<(),&'static str> {
    if state.get()==RegistrationGrantState::GenerationReserved { return Err("strict claim owns this registration"); }
    state.set(RegistrationGrantState::LegacyGrantAttempted);Ok(())
}
#[cfg(feature = "qualification-catalog")]
fn reserve_generation_state(state:&std::cell::Cell<RegistrationGrantState>)->Result<(),&'static str> {
    match state.get() {
        RegistrationGrantState::Fresh=>{state.set(RegistrationGrantState::GenerationReserved);Ok(())},
        RegistrationGrantState::LegacyGrantAttempted=>Err("legacy preparation already attempted; fresh profile required"),
        RegistrationGrantState::GenerationReserved=>Err("registration already reserved; fresh profile required"),
    }
}

//! Deployment authority selection from the retained authenticated host identity.
//!
//! The compiled policy is deliberately empty. Adding an entry requires reviewed
//! deployment policy, native qualification and an actual evidence producer. This
//! owner does not establish current process containment or issue spawn permits.

use super::{
    AuthenticatedWindowsQualificationCatalog, CatalogError, WindowsQualificationAuthority,
    WindowsQualificationIdentity, verify_windows_qualification_catalog,
};
use crate::{ArtifactDigest, VerifiedCurrentWindowsImage, VerifiedWindowsImage};
use std::os::windows::fs::FileExt as _;
use sha2::{Digest as _, Sha256};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PolicyRecipe { ClosedPrimaryV1 }

impl PolicyRecipe {
    const fn version(self) -> &'static str { match self { Self::ClosedPrimaryV1 => "keld.windows.primary-read-execute/v1" } }
    const fn runtime_member(self) -> &'static str { match self { Self::ClosedPrimaryV1 => "bun.exe" } }
    const fn read_execute_members(self) -> &'static [&'static str] {
        match self { Self::ClosedPrimaryV1 => &["bun.exe", "code/main.js", "code/kipc-transport.js"] }
    }
}

// Stable policy constraints do not embed the containing Host's own byte hash.
#[derive(Debug)]
struct PolicyIdentity {
    artifact_digest: [u8; 32],
    os_policy_digest: [u8; 32],
    policy_generation: u64,
}
impl PolicyIdentity {
    fn with_observed_creator(&self, recipe: PolicyRecipe, creator_digest: [u8; 32]) -> WindowsQualificationIdentity {
        WindowsQualificationIdentity {
            artifact_digest: self.artifact_digest,
            template_digest: full_template_sha256(recipe, self, creator_digest),
            creator_digest, os_policy_digest: self.os_policy_digest, policy_generation: self.policy_generation,
        }
    }
}

// Canonical transcript v1: domain (including NUL), length-prefixed fixed recipe
// bytes, runtime SHA-256, final signed creator SHA-256, OS-policy digest, and
// little-endian u64 policy generation. No compiled full-template/self-image hash.
fn full_template_sha256(
    recipe: PolicyRecipe,
    policy: &PolicyIdentity,
    creator: [u8; 32],
) -> [u8; 32] {
    let mut hash = Sha256::new();
    hash.update(b"keld.windows.qualified-template/v1\0");
    // This is a closed enum, not a caller string or serialized catalog field.
    let recipe_bytes: &[u8] = match recipe {
        PolicyRecipe::ClosedPrimaryV1 => b"closed-primary/v1;files=bun.exe,code/main.js,code/kipc-transport.js;file-access=read-execute;directories=traverse;role-data=private;caps=zero;aap=opt-out;handles=explicit;environment=explicit",
    };
    hash.update((recipe_bytes.len() as u64).to_le_bytes());
    hash.update(recipe_bytes);
    hash.update(policy.artifact_digest);
    hash.update(creator);
    hash.update(policy.os_policy_digest);
    hash.update(policy.policy_generation.to_le_bytes());
    hash.finalize().into()
}

#[derive(Debug)]
struct PolicyEntry {
    publisher_scope: [u8; 32],
    app_id: &'static str,
    qualification_key: [u8; 32],
    recipe: PolicyRecipe,
    identity: PolicyIdentity,
}

// There is no environment, CLI, catalog or public setter for this table.
static DEPLOYMENT_POLICIES: &[PolicyEntry] = &[];

/// Refusal to authenticate assertions under the compiled deployment policy.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum DeploymentCatalogError {
    /// No reviewed qualification authority is configured for the verified host.
    UnsupportedPolicy,
    /// More than one compiled entry selected the same authenticated host.
    AmbiguousPolicy,
    /// The selected policy key or catalog failed the single verifier.
    Catalog(CatalogError),
    /// The retained verified creator image could not be read within the bound.
    CreatorImage {
        /// Exact underlying read or size failure detail.
        detail: String,
        /// Native OS status when the underlying failure supplied one.
        raw_os_error: Option<i32>,
    },
}

/// A catalog selected by the private compiled policy for this retained host.
/// Owns immutable sealed assertions and the same preverified Host Arc.
/// It may cross the supervisor thread boundary without re-verification; native
/// registration, grants and generation-stage ownership remain thread-local.
///
/// Unlike diagnostic signature verification, callers cannot supply the authority
/// or expected identity that creates this owner. This is still not a live permit.
#[derive(Debug)]
pub struct DeploymentQualifiedWindowsCatalog {
    host: std::sync::Arc<VerifiedCurrentWindowsImage>,
    catalog: AuthenticatedWindowsQualificationCatalog,
    recipe: PolicyRecipe,
}
impl DeploymentQualifiedWindowsCatalog {
    /// The same retained authenticated host used for private policy selection.
    #[must_use]
    pub fn host(&self) -> &VerifiedWindowsImage { self.host.image() }
    /// Read-only authenticated assertions, not live generation observations.
    #[must_use]
    pub const fn catalog(&self) -> &AuthenticatedWindowsQualificationCatalog { &self.catalog }
    /// Returns only the access recipe selected by the same private deployment entry.
    /// The complete archive inventory remains independently authenticated by Update.
    #[must_use]
    pub const fn primary_read_recipe(&self) -> WindowsClosedPrimaryRecipe<'_> {
        WindowsClosedPrimaryRecipe { catalog: self }
    }

}

/// Borrowed closed access recipe from deployment policy, never a caller list.
///
/// These three files are an access subset, not a claim that every archive has
/// only three entries. The consuming stage must compare SHA-256 of its actual
/// retained runtime bytes and retain this policy owner through grant lifetime.
#[derive(Debug)]
pub struct WindowsClosedPrimaryRecipe<'catalog> {
    catalog: &'catalog DeploymentQualifiedWindowsCatalog,
}
impl WindowsClosedPrimaryRecipe<'_> {
    /// Exact version of this compiled read/execute subset.
    #[must_use]
    pub const fn version(&self) -> &'static str { self.catalog.recipe.version() }
    /// Canonical runtime member whose actual bytes require SHA-256 comparison.
    #[must_use]
    pub const fn runtime_member(&self) -> &'static str { self.catalog.recipe.runtime_member() }
    /// Exact file members receiving the existing `ReadExecute` grant mode.
    /// Directory ancestry receives traversal only under its separate owner.
    #[must_use]
    pub const fn read_execute_members(&self) -> &'static [&'static str] {
        self.catalog.recipe.read_execute_members()
    }
    /// Expected SHA-256 of runtime executable bytes, not archive BLAKE3 or signer identity.
    #[must_use]
    pub fn runtime_artifact_digest(&self) -> ArtifactDigest {
        ArtifactDigest(self.catalog.catalog.identity().artifact_digest)
    }
}

/// Verifies catalog assertions using only a compiled policy for a verified host.
///
/// Publisher and app id are read from the retained Authenticode owner, never a
/// caller string. The current table is empty, so this API always refuses before
/// signature work. The returned type, when a policy is later reviewed, would
/// still contain assertions only: it cannot produce live admission or a permit.
///
/// # Errors
/// Refuses absent/ambiguous compiled policy, invalid authority or catalog data.
/// No weaker launch mode is selected by a refusal.
pub fn verify_catalog_for_windows_host(
    host: std::sync::Arc<VerifiedCurrentWindowsImage>,
    bytes: &[u8],
    signature: &[u8; 64],
) -> Result<DeploymentQualifiedWindowsCatalog, DeploymentCatalogError> {
    let identity = host.image().identity();
    let policy = select_policy(
        DEPLOYMENT_POLICIES,
        identity.publisher_scope(),
        identity.app_id(),
    )?;
    let authority = WindowsQualificationAuthority::from_trusted_public_key(
        &policy.qualification_key,
    ).map_err(DeploymentCatalogError::Catalog)?;
    let creator = retained_creator_sha256(host.image().file()).map_err(|error| DeploymentCatalogError::CreatorImage {
        detail: error.to_string(), raw_os_error: error.raw_os_error(),
    })?;
    let expected = policy.identity.with_observed_creator(policy.recipe, creator);
    let catalog = verify_windows_qualification_catalog(&authority, &expected, bytes, signature)
        .map_err(DeploymentCatalogError::Catalog)?;
    Ok(DeploymentQualifiedWindowsCatalog { host, catalog, recipe: policy.recipe })
}

// Bounded point-in-time bytes of the same read-sharing Authenticode-pinned file.
// This does not prove it is the current process image; Core's current-executable
// owner must supply and retain that binding before any generation permit.
fn retained_creator_sha256(file: &std::fs::File) -> std::io::Result<[u8; 32]> {
    const MAX_CREATOR_BYTES: u64 = 512 * 1024 * 1024;
    let metadata = file.metadata()?;
    if !metadata.is_file() || metadata.len() == 0 || metadata.len() > MAX_CREATOR_BYTES {
        return Err(std::io::Error::new(std::io::ErrorKind::InvalidData, "creator image must be a regular file of 1..=512 MiB"));
    }
    let size = metadata.len();
    let mut hash = Sha256::new();
    let mut offset = 0_u64;
    let mut buffer = [0_u8; 16 * 1024];
    while offset < size {
        let wanted = usize::try_from((size - offset).min(buffer.len() as u64)).map_err(std::io::Error::other)?;
        let count = file.seek_read(&mut buffer[..wanted], offset)?;
        if count == 0 { return Err(std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "creator image shortened")); }
        hash.update(&buffer[..count]);
        offset += u64::try_from(count).map_err(std::io::Error::other)?;
    }
    if file.metadata()?.len() != size {
        return Err(std::io::Error::new(std::io::ErrorKind::InvalidData, "creator image length changed"));
    }
    Ok(hash.finalize().into())
}

// Pure selection helper is private; external callers cannot assert an identity
// to obtain this policy or replace the compiled table.
fn select_policy<'a>(
    policies: &'a [PolicyEntry],
    publisher_scope: &[u8; 32],
    app_id: &str,
) -> Result<&'a PolicyEntry, DeploymentCatalogError> {
    let mut matches = policies.iter().filter(|entry| {
        entry.publisher_scope == *publisher_scope && entry.app_id == app_id
            && entry.recipe == PolicyRecipe::ClosedPrimaryV1
    });
    let selected = matches.next().ok_or(DeploymentCatalogError::UnsupportedPolicy)?;
    if matches.next().is_some() {
        return Err(DeploymentCatalogError::AmbiguousPolicy);
    }
    Ok(selected)
}

