        let recipe = fixture().recipe;
        assert_eq!(recipe.version(), "keld.windows.primary-read-execute/v1");
        assert_eq!(recipe.runtime_member(), "bun.exe");
        assert_eq!(recipe.read_execute_members(), &["bun.exe", "code/main.js", "code/kipc-transport.js"]);
        assert!(!recipe.read_execute_members().contains(&"renderer/index.html"));
        assert!(!recipe.read_execute_members().contains(&"code/extra.js"));
