    }

    #[test]
    fn observed_creator_is_not_a_compiled_self_hash() {
        let policy = fixture();
        let one = policy.identity.with_observed_creator(policy.recipe, [7; 32]);
        let two = policy.identity.with_observed_creator(policy.recipe, [8; 32]);
        assert_eq!(one.creator_digest, [7; 32]);
        assert_ne!(one, two);
        assert_eq!(one.artifact_digest, two.artifact_digest);
        assert_ne!(one.template_digest, two.template_digest);
        // A legacy compiled template cannot be reused as the new full identity.
        let mut legacy = one.clone();
        legacy.template_digest = [4; 32];
        assert_ne!(legacy, one);
    }
    #[test]
    fn creator_hash_is_positional_sha256_and_rejects_empty_image() {
        use std::io::{Seek as _, SeekFrom, Write as _};
        let mut file = tempfile::tempfile().expect("private byte fixture");
        assert!(retained_creator_sha256(&file).is_err());
        file.write_all(b"abc").expect("fixture bytes");
        file.seek(SeekFrom::Start(1)).expect("nonzero shared cursor");
        let expected = [0xba,0x78,0x16,0xbf,0x8f,0x01,0xcf,0xea,0x41,0x41,0x40,0xde,0x5d,0xae,0x22,0x23,
            0xb0,0x03,0x61,0xa3,0x96,0x17,0x7a,0x9c,0xb4,0x10,0xff,0x61,0xf2,0x00,0x15,0xad];
        assert_eq!(retained_creator_sha256(&file).expect("actual fixture SHA256"), expected);
        file.seek(SeekFrom::Start(0)).expect("controlled fixture mutation");
        file.write_all(b"abd").expect("same-size changed bytes");
        assert_ne!(retained_creator_sha256(&file).expect("changed bytes hash"), expected);
    }

    #[test]
    fn full_template_binds_every_stable_constraint_and_creator() {
        let mut policy = fixture();
        let expected = policy.identity.with_observed_creator(policy.recipe, [7; 32]);
        policy.identity.artifact_digest[0] ^= 1;
        assert_ne!(policy.identity.with_observed_creator(policy.recipe, [7; 32]).template_digest, expected.template_digest);
        policy.identity.artifact_digest[0] ^= 1;
        policy.identity.os_policy_digest[0] ^= 1;
        assert_ne!(policy.identity.with_observed_creator(policy.recipe, [7; 32]).template_digest, expected.template_digest);
        policy.identity.os_policy_digest[0] ^= 1;
        policy.identity.policy_generation += 1;
        assert_ne!(policy.identity.with_observed_creator(policy.recipe, [7; 32]).template_digest, expected.template_digest);
        assert_ne!(expected.template_digest, expected.creator_digest);
        assert_ne!(expected.template_digest, expected.artifact_digest);
    }

    #[test]
    fn creator_hash_covers_multibuffer_bytes_from_nonzero_cursor() {
        use std::io::{Seek as _, SeekFrom, Write as _};
        let bytes: Vec<u8> = (0..32_799).map(|i| (i % 251) as u8).collect();
        let mut file = tempfile::tempfile().expect("private fixture");
        file.write_all(&bytes).expect("full fixture");
        file.seek(SeekFrom::Start(19)).expect("nonzero cursor");
        let expected = [216, 131, 170, 235, 223, 29, 112, 41, 181, 42, 82, 110, 157, 212, 24, 112, 99, 10, 15, 183, 166, 88, 190, 214, 191, 150, 157, 75, 45, 98, 206, 5];
        assert_eq!(retained_creator_sha256(&file).expect("positional full image"), expected);
        // No preservation of the shared cursor is promised by Windows seek_read.
    }

}

//! Opt-in authentication of Windows qualification assertions, not live admission.
//!
//! No default authority, installation migration, `HostFacts` or generation permit
//! is supplied here. A signed assertion still requires independent native evidence
//! and a matching retained generation before any role may be admitted.

use ed25519_dalek::{Signature, VerifyingKey};
use serde::Deserialize;

const DOMAIN: &[u8] = b"keld.windows-qualification-catalog/v1\0";
const MAX_BYTES: usize = 64 * 1024;

/// Explicit qualification authority; never inferred from an application signer.
#[derive(Debug)]
pub struct WindowsQualificationAuthority(VerifyingKey);

impl WindowsQualificationAuthority {
    /// Uses the caller's independently trusted qualification public key.
    ///
    /// # Errors
    /// Rejects invalid or weak Ed25519 public keys. Construction does not decide
    /// whether this authority is trusted for a deployment.
    pub fn from_trusted_public_key(key: &[u8; 32]) -> Result<Self, CatalogError> {
        let key = VerifyingKey::from_bytes(key).map_err(|_| CatalogError::Authority)?;
        if key.is_weak() {
            return Err(CatalogError::Authority);
        }
        Ok(Self(key))
    }
}

/// Exact independently selected identity expected for these assertions.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct WindowsQualificationIdentity {
    /// SHA-256 of the exact qualified runtime executable bytes.
    /// The closed-primary recipe binds this to bun.exe, never canonical TAR
    /// BLAKE3, a publisher scope, or an applied profile digest.
    pub artifact_digest: [u8; 32],
    /// Separate template identity, never a V1 applied profile digest.
    pub template_digest: [u8; 32],
    /// SHA-256 of the exact signed Host creator executable bytes.
    /// The detached catalog is signed after that image is finalized; deployment
    /// verification derives this expectation from its retained verified file.
    pub creator_digest: [u8; 32],
    /// Exact supported OS and native policy identity.
    pub os_policy_digest: [u8; 32],
    /// Exact independently selected policy generation.
    pub policy_generation: u64,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct WireCatalog {
    schema: String,
    identity: WindowsQualificationIdentity,
    rows: Vec<WireRow>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct WireRow {
    probe: String,
    layer: String,
    oracle: String,
    verdict: String,
    native_evidence_digest: [u8; 32],
    positive_control_digest: [u8; 32],
}

/// Authenticated statements bound to exact requested identities.
///
/// This value is not a proof that the current process is contained. It exposes
/// no conversion into `HostFacts`, `ProfileState`, or a spawn permit.
#[derive(Debug)]
pub struct AuthenticatedWindowsQualificationCatalog {
    identity: WindowsQualificationIdentity,
    // Retain the exact signed representation, not a reserialized approximation.
    signed_bytes: Box<[u8]>,
    authority: [u8; 32],
    signature: [u8; 64],
}

impl AuthenticatedWindowsQualificationCatalog {
    /// Returns the exact authenticated identity tuple.
    #[must_use]
    pub const fn identity(&self) -> &WindowsQualificationIdentity {
        &self.identity
    }

    /// Returns the exact authenticated payload bytes.
    #[must_use]
    pub fn signed_bytes(&self) -> &[u8] {
        &self.signed_bytes
    }

    /// Returns the exact detached signature accepted by the single verifier.
    #[must_use]
    pub const fn signature(&self) -> &[u8; 64] { &self.signature }

    /// Returns the explicit verification key, not a deployment trust decision.
    #[must_use]
    pub const fn authority_public_key(&self) -> &[u8; 32] {
        &self.authority
    }
}

/// Closed refusal categories; none permits a weaker launch fallback.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CatalogError {
    /// Invalid or weak public key.
    Authority,
    /// Empty or oversized signed document.
    Size,
    /// Signature or domain separation mismatch.
    Signature,
    /// Malformed or non-closed serialized shape.
    Shape,
    /// Unsupported catalog version.
    Version,
    /// Authenticated identity differs from the requested tuple.
    Identity,
    /// Missing, ambiguous or nonqualifying required evidence assertions.
    Rows,
}

/// Authenticates a bounded closed catalog under an explicit qualification key.
///
/// The detached signature covers DOMAIN followed by the exact supplied bytes.
/// This function performs no I/O or native security changes. It checks signed
/// assertions, not whether referenced evidence files actually prove the claims.
///
/// # Errors
/// Refuses invalid signatures, unknown/duplicate fields, unknown versions,
/// mismatched identity, and missing, duplicate or nonqualifying required rows.
pub fn verify_windows_qualification_catalog(
    authority: &WindowsQualificationAuthority,
    expected: &WindowsQualificationIdentity,
    bytes: &[u8],
    signature: &[u8; 64],
) -> Result<AuthenticatedWindowsQualificationCatalog, CatalogError> {
    if bytes.is_empty() || bytes.len() > MAX_BYTES {
        return Err(CatalogError::Size);
    }
    let mut message = Vec::with_capacity(DOMAIN.len() + bytes.len());
    message.extend_from_slice(DOMAIN);
    message.extend_from_slice(bytes);
    authority.0.verify_strict(&message, &Signature::from_bytes(signature))
        .map_err(|_| CatalogError::Signature)?;
    let catalog: WireCatalog = serde_json::from_slice(bytes).map_err(|_| CatalogError::Shape)?;
    if catalog.schema != "keld.windows-qualification-catalog/v1" {
        return Err(CatalogError::Version);
    }
    if catalog.identity != *expected
        || catalog.identity.policy_generation < crate::policy_generation_for(crate::HostOs::Windows)
    {
        return Err(CatalogError::Identity);
    }
    let required = crate::required_os_containment_probes(crate::HostOs::Windows);
    if catalog.rows.len() != required.len() {
        return Err(CatalogError::Rows);
    }
    for probe in required {
        let mut rows = catalog.rows.iter().filter(|row| row.probe == *probe);
        let row = rows.next().ok_or(CatalogError::Rows)?;
        if rows.next().is_some()
            || row.layer != "os_containment"
            || row.oracle != "os_deny"
            || row.verdict != "pass"
            || row.native_evidence_digest == [0; 32]
            || row.positive_control_digest == [0; 32]
        {
            return Err(CatalogError::Rows);
        }
    }
    Ok(AuthenticatedWindowsQualificationCatalog {
        identity: catalog.identity,
        signed_bytes: bytes.into(),
        signature: *signature,
        authority: authority.0.to_bytes(),
    })
}

