#[cfg(test)]
mod tests {
    use super::*;
    use ed25519_dalek::{Signer as _, SigningKey};
    use serde_json::json;

    fn fixture() -> (SigningKey, WindowsQualificationIdentity, serde_json::Value) {
        // Deterministic test key only; no deployment authority or native evidence.
        let key = SigningKey::from_bytes(&[7; 32]);
        let identity = WindowsQualificationIdentity {
            artifact_digest: [1; 32], template_digest: [2; 32],
            creator_digest: [3; 32], os_policy_digest: [4; 32], policy_generation: 2,
        };
        let rows: Vec<_> = crate::required_os_containment_probes(crate::HostOs::Windows).iter().map(|probe| json!({
            "probe": probe, "layer": "os_containment", "oracle": "os_deny",
            "verdict": "pass", "native_evidence_digest": vec![5; 32],
            "positive_control_digest": vec![6; 32],
        })).collect();
        let wire = json!({"schema":"keld.windows-qualification-catalog/v1",
            "identity": {"artifact_digest":vec![1;32], "template_digest":vec![2;32],
                "creator_digest":vec![3;32], "os_policy_digest":vec![4;32], "policy_generation":2},
            "rows":rows});
        (key, identity, wire)
    }

    fn verify(key: &SigningKey, identity: &WindowsQualificationIdentity, bytes: &[u8])
        -> Result<AuthenticatedWindowsQualificationCatalog, CatalogError>
    {
        let authority = WindowsQualificationAuthority::from_trusted_public_key(
            &key.verifying_key().to_bytes()).unwrap();
        let mut message = DOMAIN.to_vec(); message.extend_from_slice(bytes);
        let signature = key.sign(&message).to_bytes();
        verify_windows_qualification_catalog(&authority, identity, bytes, &signature)
    }

    #[test]
    fn signed_assertions_preserve_exact_bytes_without_minting_admission() {
        let (key, identity, wire) = fixture();
        let bytes = serde_json::to_vec(&wire).unwrap();
        let accepted = verify(&key, &identity, &bytes).unwrap();
        assert_eq!(accepted.signed_bytes(), bytes);
        assert_eq!(accepted.identity(), &identity);
        let mut message=DOMAIN.to_vec(); message.extend_from_slice(&bytes);
        assert_eq!(accepted.signature(), &key.sign(&message).to_bytes());
        let authority=WindowsQualificationAuthority::from_trusted_public_key(&key.verifying_key().to_bytes()).unwrap();
        verify_windows_qualification_catalog(&authority,&identity,accepted.signed_bytes(),accepted.signature()).unwrap();
        let mut changed=*accepted.signature(); changed[0]^=1;
        assert!(verify_windows_qualification_catalog(&authority,&identity,accepted.signed_bytes(),&changed).is_err());
    }

    #[test]
    fn duplicate_missing_wrong_layer_and_nonpasses_refuse() {
        let (key, identity, wire) = fixture();
        for variant in 0..5 {
            let mut changed = wire.clone();
            match variant {
                0 => changed["rows"][1] = changed["rows"][0].clone(),
                1 => { changed["rows"].as_array_mut().unwrap().pop(); }
                2 => changed["rows"][0]["layer"] = json!("host_protocol"),
                3 => changed["rows"][0]["verdict"] = json!("fail"),
                _ => changed["rows"][0]["positive_control_digest"] = json!(vec![0; 32]),
            }
            assert_eq!(verify(&key, &identity, &serde_json::to_vec(&changed).unwrap()).unwrap_err(), CatalogError::Rows);
        }
    }

    #[test]
    fn signature_and_domain_are_not_optional() {
        let (key, identity, wire) = fixture();
        let bytes = serde_json::to_vec(&wire).unwrap();
        let authority = WindowsQualificationAuthority::from_trusted_public_key(&key.verifying_key().to_bytes()).unwrap();
        let wrong_domain = key.sign(&bytes).to_bytes();
        assert_eq!(verify_windows_qualification_catalog(&authority, &identity, &bytes, &wrong_domain).unwrap_err(), CatalogError::Signature);
        let other = SigningKey::from_bytes(&[8; 32]);
        let mut message = DOMAIN.to_vec(); message.extend_from_slice(&bytes);
        assert_eq!(verify_windows_qualification_catalog(&authority, &identity, &bytes, &other.sign(&message).to_bytes()).unwrap_err(), CatalogError::Signature);
    }

    #[test]
    fn signed_shape_version_and_identity_changes_refuse() {
        let (key, identity, wire) = fixture();
        let mut changed = wire.clone(); changed["extra"] = json!(true);
        assert_eq!(verify(&key, &identity, &serde_json::to_vec(&changed).unwrap()).unwrap_err(), CatalogError::Shape);
        let mut changed = wire.clone(); changed["schema"] = json!("v2");
        assert_eq!(verify(&key, &identity, &serde_json::to_vec(&changed).unwrap()).unwrap_err(), CatalogError::Version);
        let mut changed = wire; changed["identity"]["policy_generation"] = json!(3);
        assert_eq!(verify(&key, &identity, &serde_json::to_vec(&changed).unwrap()).unwrap_err(), CatalogError::Identity);
    }
    #[test]
    fn signed_raw_duplicate_fields_refuse_at_every_struct_level() {
        let (key, identity, wire) = fixture();
        let raw = serde_json::to_string(&wire).unwrap();
        let duplicate_top = raw.replacen(
            "\"schema\":", "\"schema\":\"keld.windows-qualification-catalog/v1\",\"schema\":", 1,
        );
        let duplicate_identity = raw.replacen(
            "\"policy_generation\":", "\"policy_generation\":1,\"policy_generation\":", 1,
        );
        let duplicate_row = raw.replacen(
            "\"verdict\":", "\"verdict\":\"pass\",\"verdict\":", 1,
        );
        for malformed in [duplicate_top, duplicate_identity, duplicate_row] {
            assert_ne!(malformed, raw, "raw duplicate injection must change bytes");
            // Sign the malformed raw representation itself. Value parsing here
            // would discard duplicate keys and would not exercise this boundary.
            assert_eq!(verify(&key, &identity, malformed.as_bytes()).unwrap_err(), CatalogError::Shape);
        }
    }

    #[test]
    fn signed_nested_unknown_fields_refuse() {
        let (key, identity, wire) = fixture();
        for nested_identity in [false, true] {
            let mut changed = wire.clone();
            if nested_identity {
                changed["identity"]["extra"] = json!(true);
            } else {
                changed["rows"][0]["extra"] = json!(true);
            }
            assert_eq!(verify(&key, &identity, &serde_json::to_vec(&changed).unwrap()).unwrap_err(), CatalogError::Shape);
        }
    }

    #[test]
    fn empty_and_oversized_payloads_refuse_before_signature_work() {
        let (key, identity, _) = fixture();
        let authority = WindowsQualificationAuthority::from_trusted_public_key(&key.verifying_key().to_bytes()).unwrap();
        for bytes in [Vec::new(), vec![b' '; MAX_BYTES + 1]] {
            assert_eq!(verify_windows_qualification_catalog(&authority, &identity, &bytes, &[0; 64]).unwrap_err(), CatalogError::Size);
        }
    }

    #[test]
    fn weak_public_key_refuses() {
        // Compressed Edwards identity is a valid encoding but small order.
        let mut identity_point = [0; 32];
        identity_point[0] = 1;
        assert!(VerifyingKey::from_bytes(&identity_point).unwrap().is_weak());
        assert_eq!(WindowsQualificationAuthority::from_trusted_public_key(&identity_point).unwrap_err(), CatalogError::Authority);
    }

    #[test]
    fn even_json_whitespace_change_invalidates_original_signature() {
        let (key, identity, wire) = fixture();
        let mut bytes = serde_json::to_vec(&wire).unwrap();
        let mut message = DOMAIN.to_vec(); message.extend_from_slice(&bytes);
        let signature = key.sign(&message).to_bytes();
        bytes.push(b' ');
        let authority = WindowsQualificationAuthority::from_trusted_public_key(&key.verifying_key().to_bytes()).unwrap();
        assert_eq!(verify_windows_qualification_catalog(&authority, &identity, &bytes, &signature).unwrap_err(), CatalogError::Signature);
    }

    #[test]
    fn unknown_probe_and_missing_native_evidence_refuse() {
        let (key, identity, wire) = fixture();
        for unknown_probe in [false, true] {
            let mut changed = wire.clone();
            if unknown_probe {
                changed["rows"][0]["probe"] = json!("unknown_probe");
            } else {
                changed["rows"][0]["native_evidence_digest"] = json!(vec![0; 32]);
            }
            assert_eq!(verify(&key, &identity, &serde_json::to_vec(&changed).unwrap()).unwrap_err(), CatalogError::Rows);
        }
    }

    #[test]
    fn each_signed_identity_field_must_match_exactly() {
        let (key, identity, wire) = fixture();
        for field in ["artifact_digest", "template_digest", "creator_digest", "os_policy_digest", "policy_generation"] {
            let mut changed = wire.clone();
            changed["identity"][field] = if field == "policy_generation" {
                json!(3)
            } else {
                json!(vec![9; 32])
            };
            assert_eq!(verify(&key, &identity, &serde_json::to_vec(&changed).unwrap()).unwrap_err(), CatalogError::Identity, "field: {field}");
        }
    }

    #[test]
    fn appended_unknown_row_refuses() {
        let (key, identity, mut wire) = fixture();
        let mut extra = wire["rows"][0].clone();
        extra["probe"] = json!("unknown_extra_probe");
        wire["rows"].as_array_mut().unwrap().push(extra);
        assert_eq!(verify(&key, &identity, &serde_json::to_vec(&wire).unwrap()).unwrap_err(), CatalogError::Rows);
    }

    #[test]
    fn absent_native_evidence_field_is_a_shape_error() {
        let (key, identity, mut wire) = fixture();
        let removed = wire["rows"][0].as_object_mut().unwrap().remove("native_evidence_digest");
        assert!(removed.is_some());
        assert_eq!(verify(&key, &identity, &serde_json::to_vec(&wire).unwrap()).unwrap_err(), CatalogError::Shape);
    }

    #[test]
    fn wrong_oracle_refuses_with_qualifying_layer_and_verdict() {
        let (key, identity, mut wire) = fixture();
        assert_eq!(wire["rows"][0]["layer"], json!("os_containment"));
        assert_eq!(wire["rows"][0]["verdict"], json!("pass"));
        wire["rows"][0]["oracle"] = json!("host_protocol");
        assert_eq!(verify(&key, &identity, &serde_json::to_vec(&wire).unwrap()).unwrap_err(), CatalogError::Rows);
    }

    #[test]
    fn matching_legacy_policy_identity_still_refuses_windows_v2() {
        let (key, mut identity, mut wire) = fixture();
        identity.policy_generation = 1;
        wire["identity"]["policy_generation"] = json!(1);
        let bytes = serde_json::to_vec(&wire).unwrap();
        assert!(matches!(verify(&key, &identity, &bytes), Err(CatalogError::Identity)));
    }

}

