//! One-shot actual resource preparation. Not a spawn permit or complete profile.
#![forbid(unsafe_code)]
use std::collections::{BTreeMap,BTreeSet};
use std::fs::File;
use std::rc::Rc;
use sha2::{Digest as _,Sha256};
