/// Closed access roles. Directory names are canonical archive labels, not paths opened here.
#[derive(Debug,Clone,PartialEq,Eq,PartialOrd,Ord)]
pub enum WindowsGenerationResourceRole {
    /// Fresh workspace directory.
    Workspace,
    /// Fresh payload wrapper directory.
    PayloadRoot,
    /// Canonical extracted tree root.
    TreeRoot,
    /// One canonical inventory directory, traversal only.
    Directory(String),
    /// Exact recipe runtime member bun.exe.
    Runtime,
    /// Exact recipe main module code/main.js.
    Main,
    /// Exact recipe transport module code/kipc-transport.js.
    Transport,
    /// Separate fresh mutable role-data directory.
    RoleData,
}
impl WindowsGenerationResourceRole {
    fn label(&self)->String { match self {
        Self::Workspace=>"workspace".into(),Self::PayloadRoot=>"payload-root".into(),Self::TreeRoot=>"tree-root".into(),
        Self::Directory(name)=>format!("directory:{name}"),Self::Runtime=>"file:bun.exe".into(),
        Self::Main=>"file:code/main.js".into(),Self::Transport=>"file:code/kipc-transport.js".into(),Self::RoleData=>"role-data".into(),
    } }
    fn access(&self)->WindowsProfilePathAccess { match self {
        Self::Runtime|Self::Main|Self::Transport=>WindowsProfilePathAccess::ReadExecute,
        Self::RoleData=>WindowsProfilePathAccess::RolePrivate,
        _=>WindowsProfilePathAccess::Traverse,
    } }
    fn is_directory(&self)->bool { !matches!(self,Self::Runtime|Self::Main|Self::Transport) }
    fn mask_flags(&self)->(u32,u32) { match self.access() {
        WindowsProfilePathAccess::Traverse=>(0x20,0),WindowsProfilePathAccess::ReadExecute=>(0x12_00a9,0),
        WindowsProfilePathAccess::RolePrivate=>(0x12_01bf,3),
    } }
}

/// Unique pre-write claim. Reservation permanently disables legacy grants on its
/// registration. Failure never resets it, and only this owner may perform grants.
#[derive(Debug)]
pub struct WindowsGenerationGrantClaim {
    registration:Rc<WindowsProfileRegistration>,
    catalog:std::sync::Arc<DeploymentQualifiedWindowsCatalog>,
    expected:BTreeSet<WindowsGenerationResourceRole>,
    attempted:BTreeSet<WindowsGenerationResourceRole>,
    failed:bool,
}
/// Refused reservation retains its supplied owners; no ACL operation occurred.
#[derive(Debug)]
pub struct WindowsGenerationClaimFailure {
    registration:Rc<WindowsProfileRegistration>,catalog:std::sync::Arc<DeploymentQualifiedWindowsCatalog>,
    expected:Vec<WindowsGenerationResourceRole>,detail:String,
}
impl WindowsGenerationClaimFailure {
    /// Exact pre-write refusal, with all supplied owners retained in this value.
    #[must_use] pub fn detail(&self)->&str { &self.detail }
}
impl WindowsGenerationGrantClaim {
    /// Reserves a registration before the first ACL mutation, under the actual
    /// opaque deployment catalog. Labels describe resources only; complete archive
    /// authentication and label-to-object binding stay with the Update composer.
    /// # Errors
    /// Refuses missing/duplicate/invalid roles, unsupported recipe, deleted or
    /// already-claimed registration. No existing claim or latch is reset.
    pub fn reserve(registration:Rc<WindowsProfileRegistration>,catalog:std::sync::Arc<DeploymentQualifiedWindowsCatalog>,
        roles:Vec<WindowsGenerationResourceRole>) -> Result<Self,WindowsGenerationClaimFailure> {
        let checked=validate_roles(&roles).and_then(|expected|{
            let recipe=catalog.primary_read_recipe();
            if recipe.version()!="keld.windows.primary-read-execute/v1"
                || recipe.read_execute_members()!=["bun.exe","code/main.js","code/kipc-transport.js"] {
                return Err("unsupported closed primary recipe".to_owned());
            }
            registration.capabilities().map_err(|e|e.to_string())?;
            super::reserve_generation_state(&registration.grant_state).map_err(str::to_owned)?;
            Ok(expected)
        });
        match checked {
            Ok(expected)=>Ok(Self { registration,catalog,expected,attempted:BTreeSet::new(),failed:false }),
            Err(detail)=>Err(WindowsGenerationClaimFailure { registration,catalog,expected:roles,detail }),
        }
    }
    /// Same exact registration; this observation cannot construct another claim.
    #[must_use] pub fn registration(&self)->&Rc<WindowsProfileRegistration> { &self.registration }
    /// Consumes a role's one permitted grant attempt before any mutation. The
    /// helper file is transferred to the existing single ACL/closed-receipt owner.
    /// # Errors
    /// Refuses a role outside the fixed plan, a second attempt, wrong object kind,
    /// or native grant failure. The returned failure retains the object/registration.
    pub fn publish(&mut self,role:WindowsGenerationResourceRole,destination:File)
        ->Result<WindowsGenerationGrantedMember,WindowsGrantReceiptFailure> {
        if self.failed || !self.expected.contains(&role) || !self.attempted.insert(role.clone()) {
            self.failed=true;
            return Err(crate::windows_profile_grant::refused_generation_grant(Rc::clone(&self.registration),destination,
                "role absent or already attempted; claim cannot be retried"));
        }
        let directory=match destination.metadata() {
            Ok(metadata)=>metadata.is_dir(),
            Err(_)=>{ self.failed=true; return Err(crate::windows_profile_grant::refused_generation_grant(Rc::clone(&self.registration),destination,"grant object metadata failed")); },
        };
        if directory!=role.is_directory() {
            self.failed=true;
            return Err(crate::windows_profile_grant::refused_generation_grant(Rc::clone(&self.registration),destination,"grant object kind differs from role"));
        }
        match WindowsProfileRegistration::publish_generation_retained_grant(self,destination,role.access()) {
            Ok(receipt)=>Ok(WindowsGenerationGrantedMember { role,receipt }),Err(failure)=>{ self.failed=true;Err(failure) },
        }
    }
    /// Consumes the claim and its actual closed receipts into a non-Clone resource
    /// owner. Success is not KEL-78 admission, token evidence or process permission.
    /// # Errors
    /// Refuses incomplete/duplicate/wrong-registration/object/mask observations,
    /// native revalidation failure or drift. Failure keeps claim and all receipts.
    pub fn prepare_resources(self,grants:Vec<WindowsGenerationGrantedMember>)
        ->Result<WindowsPreparedGenerationResources,WindowsGenerationPreparationFailure> {
        match resource_digest(&self,&grants) {
            Ok(digest)=>Ok(WindowsPreparedGenerationResources { claim:self,grants,digest }),
            Err(detail)=>Err(WindowsGenerationPreparationFailure { claim:self,grants,detail }),
        }
    }
}

/// Role-to-object association minted only by the unique claim that performed the
/// native grant. No public fields, constructor, Clone or relabeling conversion.
#[derive(Debug)]
pub struct WindowsGenerationGrantedMember { role:WindowsGenerationResourceRole,receipt:WindowsClosedGrantReceipt }
impl WindowsGenerationGrantedMember {
    /// Immutable role selected before the native mutation.
    #[must_use] pub const fn role(&self)->&WindowsGenerationResourceRole { &self.role }
    /// Actual opaque readback, for comparison to Update's retained stage pin.
    #[must_use] pub const fn receipt(&self)->&WindowsClosedGrantReceipt { &self.receipt }
}

/// SHA-256 of actual retained resource observations under its own domain. Never
/// a template digest, complete archive identity, or full applied ProfileDigest.
#[derive(Debug,Clone,Copy,PartialEq,Eq)]
pub struct WindowsGenerationResourceDigest([u8;32]);
impl WindowsGenerationResourceDigest {
    /// Digest bytes for a later typed composed-generation binding, not authority.
    #[must_use] pub const fn as_bytes(&self)->&[u8;32] { &self.0 }
}
/// Actual one-shot resource custody. No Clone, raw constructor, spawn conversion
/// or unchecked cleanup/retirement API is provided.
#[derive(Debug)]
pub struct WindowsPreparedGenerationResources {
    claim:WindowsGenerationGrantClaim,
    grants:Vec<WindowsGenerationGrantedMember>,
    digest:WindowsGenerationResourceDigest,
}
impl WindowsPreparedGenerationResources {
    /// Applied resource subset identity, explicitly not the complete role profile.
    #[must_use] pub const fn resource_digest(&self)->WindowsGenerationResourceDigest { self.digest }
    /// Recheck retained readback at the future pre-create boundary.
    /// # Errors
    /// Refuses drift or unsupported native queries; does not issue a spawn permit.
    pub fn revalidate(&self)->Result<(),String> {
        if resource_digest(&self.claim,&self.grants)?!=self.digest { return Err("resource identity changed".into()); }
        Ok(())
    }
}
/// Failed consuming preparation retains the claimed profile, catalog and receipts.
#[derive(Debug)]
pub struct WindowsGenerationPreparationFailure {
    claim:WindowsGenerationGrantClaim,grants:Vec<WindowsGenerationGrantedMember>,detail:String,
}
impl WindowsGenerationPreparationFailure {
    /// Exact refusal, without releasing failure custody or permitting retries.
    #[must_use] pub fn detail(&self)->&str { &self.detail }
}

fn validate_roles(roles:&[WindowsGenerationResourceRole])->Result<BTreeSet<WindowsGenerationResourceRole>,String> {
    use WindowsGenerationResourceRole as R;
    let set:BTreeSet<_>=roles.iter().cloned().collect();
    if set.len()!=roles.len() { return Err("duplicate generation resource role".into()); }
    for required in [R::Workspace,R::PayloadRoot,R::TreeRoot,R::Directory("code".into()),R::Runtime,R::Main,R::Transport,R::RoleData] {
        if !set.contains(&required) { return Err(format!("required role absent: {}",required.label())); }
    }
    for role in roles { if let R::Directory(name)=role {
        crate::validate_windows_package_paths(&[name.as_str()])?;
    } }
    Ok(set)
}
fn resource_digest(claim:&WindowsGenerationGrantClaim,grants:&[WindowsGenerationGrantedMember])
    ->Result<WindowsGenerationResourceDigest,String> {
    if claim.failed { return Err("failed claim cannot prepare resources".into()); }
    if claim.expected!=claim.attempted { return Err("not every claimed role was attempted exactly once".into()); }
    let mut ordered=BTreeMap::new();let mut objects=BTreeSet::new();let mut sid:Option<&[u8]>=None;
    for grant in grants {
        let role=&grant.role;let receipt=&grant.receipt;
        if !claim.expected.contains(role)||ordered.insert(role,receipt).is_some() { return Err("missing or duplicate receipt role".into()); }
        if !Rc::ptr_eq(&claim.registration,receipt.registration()) { return Err("receipt belongs to another registration".into()); }
        receipt.revalidate().map_err(|e|e.to_string())?;
        if (receipt.permissions(),receipt.inheritance())!=role.mask_flags() { return Err("receipt access differs from closed role".into()); }
        let identity=receipt.object_identity();
        if !objects.insert((identity.volume(),*identity.file())) { return Err("two roles alias one actual object".into()); }
        if let Some(expected)=sid { if expected!=receipt.package_sid() { return Err("actual package SID differs across grants".into()); } }
        else { sid=Some(receipt.package_sid()); }
    }
    if ordered.len()!=claim.expected.len() { return Err("required grant receipt absent".into()); }
    let rows:Vec<_>=ordered.into_iter().map(|(role,receipt)| {
        let id=receipt.object_identity();
        ResourceDigestRow { label:role.label(),volume:id.volume(),file:*id.file(),permissions:receipt.permissions(),
            inheritance:receipt.inheritance(),descriptor:receipt.descriptor() }
    }).collect();
    Ok(finish_resource_digest(claim.catalog.catalog().identity(),claim.catalog.catalog().signed_bytes(),
        claim.catalog.catalog().authority_public_key(),sid.ok_or_else(||"no registration observations".to_owned())?,&rows))
}
struct ResourceDigestRow<'a> { label:String,volume:u64,file:[u8;16],permissions:u32,inheritance:u32,descriptor:&'a str }
fn finish_resource_digest(identity:&crate::windows_qualification_catalog::WindowsQualificationIdentity,
    catalog_bytes:&[u8],authority:&[u8;32],sid:&[u8],rows:&[ResourceDigestRow<'_>])->WindowsGenerationResourceDigest {
    let mut hash=Sha256::new();hash.update(b"keld.windows.applied-generation-resources/v1\0");
    hash.update(identity.template_digest);hash.update(identity.creator_digest);hash.update(identity.artifact_digest);
    hash.update(identity.os_policy_digest);hash.update(identity.policy_generation.to_le_bytes());
    hash.update(Sha256::digest(catalog_bytes));hash_field(&mut hash,authority);hash_field(&mut hash,sid);
    hash.update((rows.len() as u64).to_le_bytes());
    for row in rows {
        hash_field(&mut hash,row.label.as_bytes());hash.update(row.volume.to_le_bytes());hash.update(row.file);
        hash.update(row.permissions.to_le_bytes());hash.update(row.inheritance.to_le_bytes());hash_field(&mut hash,row.descriptor.as_bytes());
    }
    WindowsGenerationResourceDigest(hash.finalize().into())
}

fn hash_field(hash:&mut Sha256,value:&[u8]) { hash.update((value.len() as u64).to_le_bytes());hash.update(value); }

#[cfg(test)]
mod tests {
    use super::*;
    fn roles()->Vec<WindowsGenerationResourceRole> { use WindowsGenerationResourceRole as R;
        vec![R::Workspace,R::PayloadRoot,R::TreeRoot,R::Directory("code".into()),R::Runtime,R::Main,R::Transport,R::RoleData] }
    #[test]
    fn closed_plan_refuses_missing_duplicate_and_escaping_directory() {
        let valid=roles();assert_eq!(validate_roles(&valid).unwrap().len(),8);
        for index in 0..valid.len() { let mut missing=valid.clone();missing.remove(index);assert!(validate_roles(&missing).is_err()); }
        let mut duplicate=valid.clone();duplicate.push(WindowsGenerationResourceRole::Runtime);assert!(validate_roles(&duplicate).is_err());
        for path in ["../escape","code/../escape","","C:/outside"] {
            let mut bad=valid.clone();bad.push(WindowsGenerationResourceRole::Directory(path.into()));assert!(validate_roles(&bad).is_err());
        }
    }
    #[test]
    fn role_access_is_closed_and_data_never_readonly_code() {
        use WindowsGenerationResourceRole as R;
        assert_eq!(R::RoleData.mask_flags(),(0x1201bf,3));
        for role in [R::Runtime,R::Main,R::Transport] {assert_eq!(role.mask_flags(),(0x1200a9,0));assert!(!role.is_directory());}
        for role in [R::Workspace,R::PayloadRoot,R::TreeRoot,R::Directory("code".into())] { assert_eq!(role.mask_flags(),(0x20,0));assert!(role.is_directory()); }
    }
    #[test]
    fn one_shot_claim_is_sticky_even_after_failed_work() {
        use super::super::{RegistrationGrantState as S,begin_legacy_grant_state,reserve_generation_state};
        let state=std::cell::Cell::new(S::Fresh);
        reserve_generation_state(&state).expect("fresh reservation");
        assert!(reserve_generation_state(&state).is_err());assert!(begin_legacy_grant_state(&state).is_err());
        assert_eq!(state.get(),S::GenerationReserved);
        let state=std::cell::Cell::new(S::Fresh);
        begin_legacy_grant_state(&state).expect("ordinary existing mechanism");
        // Later preparation/publication failure never resets this transition.
        assert_eq!(state.get(),S::LegacyGrantAttempted);
        assert!(reserve_generation_state(&state).is_err());
        begin_legacy_grant_state(&state).expect("existing legacy retries unchanged");
        assert_eq!(state.get(),S::LegacyGrantAttempted);
    }
    #[test]
    fn resource_transcript_binds_every_observed_field_and_identity_domain() {
        // Pure serialization controls only; these fixtures are not native evidence.
        let identity=crate::windows_qualification_catalog::WindowsQualificationIdentity {
            artifact_digest:[1;32],template_digest:[2;32],creator_digest:[3;32],os_policy_digest:[4;32],policy_generation:2 };
        let row=||ResourceDigestRow {label:"file:bun.exe".into(),volume:7,file:[8;16],permissions:0x1200a9,inheritance:0,descriptor:"O:fixtureD:fixture"};
        let original=finish_resource_digest(&identity,b"catalog",&[9;32],b"sid",&[row()]);
        assert_ne!(original.as_bytes(),&identity.template_digest);
        assert_ne!(original.as_bytes(),&identity.artifact_digest);
        for field in 0..6 {
            let mut changed=row();match field {0=>changed.label.push('x'),1=>changed.volume+=1,2=>changed.file[15]^=1,
                3=>changed.permissions^=1,4=>changed.inheritance^=1,_=>changed.descriptor="different"};
            assert_ne!(original,finish_resource_digest(&identity,b"catalog",&[9;32],b"sid",&[changed]));
        }
        for field in 0..5 {
            let mut changed=identity.clone();match field {0=>changed.artifact_digest[0]^=1,1=>changed.template_digest[0]^=1,
                2=>changed.creator_digest[0]^=1,3=>changed.os_policy_digest[0]^=1,_=>changed.policy_generation+=1};
            assert_ne!(original,finish_resource_digest(&changed,b"catalog",&[9;32],b"sid",&[row()]));
        }
        assert_ne!(original,finish_resource_digest(&identity,b"changed catalog",&[9;32],b"sid",&[row()]));
        assert_ne!(original,finish_resource_digest(&identity,b"catalog",&[10;32],b"sid",&[row()]));
        assert_ne!(original,finish_resource_digest(&identity,b"catalog",&[9;32],b"other sid",&[row()]));
        assert_ne!(original,finish_resource_digest(&identity,b"catalog",&[9;32],b"sid",&[]));
        assert_eq!(*original.as_bytes(),[249, 107, 40, 121, 104, 230, 218, 121, 202, 233, 65, 121, 56, 221, 89, 182, 79, 205, 111, 50, 95, 231, 228, 93, 192, 185, 26, 200, 85, 56, 93, 156]);
    }

